import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana'];

export default function Profile() {
  const { user } = useAuth();
  // INITIALISATION PROPRE (On utilise '' pour éviter l'erreur Select Null)
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    tarifs_matieres: [], photo_url: null
  });
  const [structure, setStructure] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetchProfileData();
  }, []);

  const fetchProfileData = async () => {
    try {
      const res = await api.get('/api/professeurs/me');
      // On s'assure qu'aucune valeur n'est nulle pour React
      const cleanData = {
        ...res.data,
        ville: res.data.ville || '',
        telephone: res.data.telephone || '',
        bio: res.data.bio || ''
      };
      setForm(cleanData);

      const resStruct = await api.get('/api/admin/referentiel/structure');
      setStructure(resStruct.data);
      setLoading(false);
    } catch (e) {
      console.error("Erreur de chargement", e);
      setLoading(false);
    }
  };

  const handleUpdate = (key, val) => setForm(prev => ({ ...prev, [key]: val }));

  // --- LOGIQUE TARIFS ---
  const isSelected = (mId, nId) => form.tarifs_matieres?.some(t => t.matiere_id === mId && t.niveau_id === nId);
  const getTarifValue = (mId, nId) => form.tarifs_matieres?.find(t => t.matiere_id === mId && t.niveau_id === nId)?.tarif || '';

  const handleToggle = (mId, nId) => {
    let list = [...(form.tarifs_matieres || [])];
    if (isSelected(mId, nId)) {
        list = list.filter(t => !(t.matiere_id === mId && t.niveau_id === nId));
    } else {
        list.push({ matiere_id: mId, niveau_id: nId, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: list });
  };

  const handlePrice = (mId, nId, p) => {
    const list = form.tarifs_matieres.map(t => 
      (t.matiere_id === mId && t.niveau_id === nId) ? { ...t, tarif: parseFloat(p) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: list });
  };

  // --- SAUVEGARDE GLOBALE (Identité + Bio + Tarifs) ---
  const handleGlobalSave = async () => {
    try {
      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        telephone: form.telephone,
        bio: form.bio,
        tarifs_complets: form.tarifs_matieres 
      };
      await api.put('/api/professeurs/me', payload);
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
      alert("✅ Profil et tarifs mis à jour en base de données !");
    } catch (e) { alert("Erreur lors de l'enregistrement"); }
  };

  if (loading) return <div style={{padding:50, textAlign:'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>
      <h2 style={{ fontFamily: 'Syne', marginBottom: 30 }}>⚙️ Paramètres du profil</h2>

      <div style={{ display: 'grid', gridTemplateColumns: '400px 1fr', gap: 30 }}>

        {/* COLONNE GAUCHE */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>👤 Mon Identité</h3>

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label>
            <input style={inpStyle} value={form.user_prenom} onChange={e => handleUpdate('user_prenom', e.target.value)} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label>
            <input style={inpStyle} value={form.user_nom} onChange={e => handleUpdate('user_nom', e.target.value)} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email (Identifiant)</label>
            <input style={{...inpStyle, opacity:0.6}} value={form.email} readOnly />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ma Bio / Présentation</label>
            <textarea style={{...inpStyle, height:100, resize:'none'}} value={form.bio} onChange={e => handleUpdate('bio', e.target.value)} placeholder="Décrivez votre expérience..." />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label>
            <input style={inpStyle} value={form.telephone} onChange={e => handleUpdate('telephone', e.target.value)} placeholder="+216..." />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
            <select style={inpStyle} value={form.ville} onChange={e => handleUpdate('ville', e.target.value)}>
               <option value="">Sélectionner...</option>
               {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
            </select>

            <button onClick={handleGlobalSave} style={{ width:'100%', background:'var(--accent)', color:'#fff', border:'none', padding:14, borderRadius:12, fontWeight:600 }}>
               {saved ? '✅ Modifié avec succès' : 'Enregistrer le profil'}
            </button>
          </div>
        </div>

        {/* COLONNE DROITE : MATIERES */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>
          {structure.map(dom => (
            <div key={dom.id} style={{ marginBottom: 30 }}>
              <div style={{ color: 'var(--accent)', fontWeight: 800, borderBottom: '1px solid var(--border)', paddingBottom: 5, marginBottom: 15 }}>📂 {dom.nom}</div>
              {dom.niveaux?.map(niv => (
                <div key={niv.id} style={{ marginBottom: 20, marginLeft: 15 }}>
                  <div style={{ fontWeight: 700, fontSize: '.9rem', marginBottom: 10 }}>🎓 {niv.nom}</div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {niv.matieres?.map(mat => {
                      const active = isSelected(mat.id, niv.id);
                      return (
                        <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: active ? 'rgba(108,99,255,0.05)' : 'var(--surface2)', padding: '10px 15px', borderRadius: 12 }}>
                          <label style={{ fontSize: '.8rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}>
                            <input type="checkbox" checked={active} onChange={() => handleToggle(mat.id, niv.id)} />
                            {mat.nom}
                          </label>
                          {active && (
                            <input type="number" value={getTarifValue(mat.id, niv.id)} onChange={e => handlePrice(mat.id, niv.id, e.target.value)} style={{ width: 50, background: 'var(--bg)', color: '#fff', border: 'none', textAlign: 'center' }} />
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          ))}
          <button onClick={handleGlobalSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 18, borderRadius: 15, fontWeight: 700 }}>Enregistrer mon catalogue</button>
        </div>
      </div>
    </div>
  );
}

const inpStyle = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '12px', fontSize: '.9rem', width: '100%', outline: 'none', marginBottom: '5px' };
